-- PG 版：与 mysql V003 语义对齐（TIMESTAMPTZ/BIGINT 有符号/JSONB/独立索引语句）
-- iam-service PostgreSQL V003 — 与 mysql/V003__tenants.sql 版本号与语义对齐。
--
-- Phase 8.1: multi-tenancy skeleton — Tenant entity + iam_users.tenant_id.
--
-- 转换规则：
--   BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY
--       -> BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY（去 UNSIGNED，IDENTITY
--          用 BY DEFAULT 保持「允许显式插 id」的 MySQL 语义）
--   DATETIME  -> TIMESTAMPTZ
--   NOW()     -> CURRENT_TIMESTAMP(3)
--   表尾 ENGINE/CHARSET -> 删除
--   表内 UNIQUE KEY uk_tenant_slug -> 独立 CREATE UNIQUE INDEX IF NOT EXISTS
--   ADD COLUMN ... AFTER id -> 去掉 AFTER（PG 无列序语义，FromRow 按列名取值）
--   DROP INDEX username（MySQL 对 V001 内联 UNIQUE 的自动索引命名）
--       -> PG 内联 UNIQUE 生成约束 iam_users_username_key，用
--          ALTER TABLE ... DROP CONSTRAINT IF EXISTS 拆除（名字一一对应）
--   ADD UNIQUE KEY uk_tenant_username -> CREATE UNIQUE INDEX IF NOT EXISTS
--   ON DUPLICATE KEY UPDATE id = id -> ON CONFLICT DO NOTHING（不指定冲突目标，
--       命中主键 id 或 uk_tenant_slug 均不动作，等价 MySQL 的 no-op update）
--   INSERT IGNORE INTO iam_roles ... VALUES -> ON CONFLICT (code) DO NOTHING
--       （选择依据：此刻 iam_roles 上唯一可命中的约束是 V001 的列级 UNIQUE(code)，
--        冲突目标确定，故显式指定列而非裸 DO NOTHING）
--
-- ⚠️ 注释里不得出现 ASCII 分号（执行器按分号切分）。

CREATE TABLE IF NOT EXISTS iam_tenants (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug         VARCHAR(64)  NOT NULL,
    display_name VARCHAR(128) NOT NULL,
    status       VARCHAR(16)  NOT NULL DEFAULT 'active',
    created_at   TIMESTAMPTZ  NOT NULL,
    updated_at   TIMESTAMPTZ  NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_tenant_slug ON iam_tenants (slug);

-- MySQL: ON DUPLICATE KEY UPDATE id = id（幂等 seed，显式插 id=1 供后续 FK DEFAULT 1 引用）
INSERT INTO iam_tenants (id, slug, display_name, status, created_at, updated_at)
VALUES (1, 'default', 'Default Tenant', 'active', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON CONFLICT DO NOTHING;

-- seed 显式占用 id=1 后 IDENTITY 序列仍停在 1（GENERATED BY DEFAULT 不为显式
-- 插入前进序列），后续自增 INSERT 会撞主键——这里把序列推到 MAX(id)。
SELECT setval(pg_get_serial_sequence('iam_tenants', 'id'),
              (SELECT COALESCE(MAX(id), 1) FROM iam_tenants));

-- MySQL: ADD COLUMN tenant_id BIGINT UNSIGNED NOT NULL DEFAULT 1 AFTER id
ALTER TABLE iam_users
    ADD COLUMN tenant_id BIGINT NOT NULL DEFAULT 1;

ALTER TABLE iam_users
    ADD CONSTRAINT fk_iam_users_tenant FOREIGN KEY (tenant_id) REFERENCES iam_tenants(id);

-- MySQL: DROP INDEX username（V001 列级 UNIQUE 在 PG 侧的约束名是 iam_users_username_key）
ALTER TABLE iam_users
    DROP CONSTRAINT IF EXISTS iam_users_username_key;

-- MySQL: ADD UNIQUE KEY uk_tenant_username (tenant_id, username)
CREATE UNIQUE INDEX IF NOT EXISTS uk_tenant_username ON iam_users (tenant_id, username);

-- MySQL: INSERT IGNORE INTO iam_roles ...（幂等 seed，命中唯一键 code 时跳过）
INSERT INTO iam_roles (id, name, code, description, data_scope, status, created_at, updated_at)
VALUES ('role-tenant-admin-seed', '租户管理员', 'tenant_admin', '租户管理员（Phase 8.1 全局共享 seed）', 'all', 'active', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3))
ON CONFLICT (code) DO NOTHING;
